<?php
declare(strict_types=1);
$private=sys_get_temp_dir().'/ectro-gov-migration-'.bin2hex(random_bytes(6));mkdir($private,0700);putenv('APP_DATA_DIR='.$private);putenv('APP_ENV=development');putenv('APP_KEY='.base64_encode(random_bytes(32)));
register_shutdown_function(function()use($private){foreach(glob($private.'/*') as $f)unlink($f);rmdir($private);});
require __DIR__.'/../app/bootstrap.php';require __DIR__.'/../app/templates.php';require __DIR__.'/../app/mysql.php';require __DIR__.'/../app/lab-api.php';
$p=new PDO('sqlite:'.$private.'/app.sqlite');$p->exec(str_replace(",'governance','rollout'",'',file_get_contents(__DIR__.'/../app/schema.sql')));$uid=id();$pid=id();$limited=id();$oid=id();$p->prepare('INSERT INTO users(id,name,email,password,role,created_at) VALUES(?,?,?,?,?,?)')->execute([$uid,'Original','old@example.test','unused','user',now()]);foreach([$pid,$limited] as $id)$p->prepare('INSERT INTO projects(id,user_id,name,created_at,updated_at) VALUES(?,?,?,?,?)')->execute([$id,$uid,'Original',now(),now()]);$full=array_values(array_diff(LAB_KINDS,['governance','rollout']));$p->prepare('INSERT INTO lab_project_config VALUES(?,?)')->execute([$pid,json_encode(['tools'=>$full,'entry'=>'readiness'])]);$restricted=json_encode(['tools'=>['landscape'],'entry'=>'landscape']);$p->prepare('INSERT INTO lab_project_config VALUES(?,?)')->execute([$limited,$restricted]);$p->prepare('INSERT INTO lab_objects(id,project_id,kind,name,content,version,updated_at) VALUES(?,?,?,?,?,?,?)')->execute([$oid,$pid,'readiness','Legacy','{}',7,now()]);$p->prepare('INSERT INTO readiness_revisions(object_id,version,actor_id,content,saved_at) VALUES(?,?,?,?,?)')->execute([$oid,7,$uid,'{}',now()]);$p=null;
$d=db();$config=json_decode(one('SELECT config FROM lab_project_config WHERE project_id=?',[$pid])['config'],true);if(count($config['tools'])!==count(LAB_KINDS)||array_diff(LAB_KINDS,$config['tools']))throw new RuntimeException('Full catalog did not extend');if(one('SELECT config FROM lab_project_config WHERE project_id=?',[$limited])['config']!==$restricted)throw new RuntimeException('Restricted tools widened');if(!one('SELECT * FROM readiness_revisions WHERE object_id=? AND version=7',[$oid]))throw new RuntimeException('Revision lost');if((int)one('SELECT version FROM lab_objects WHERE id=?',[$oid])['version']!==7)throw new RuntimeException('Source changed');if($d->query('PRAGMA foreign_key_check')->fetch())throw new RuntimeException('Foreign keys broken');echo "Governance/Project migration: full catalog extended, restricted tools preserved, readiness revisions and source versions retained.\n";
